VIDEO = {'footer': 'API Security: Mass Assignment, Data Exposure and Resource Limits  ·  Security Basics  ·  Java', 'poster': {'headline': [('API SECURITY', 'text'), ('THREE LIMITS', 'accent')], 'taglines': [('What a caller may set, may see, and may ask for', 'gold')], 'before': {'code': '{"role": "admin"} -> 200 role admin', 'note': 'Whatever the caller sends becomes a field', 'tag': 'BEFORE'}, 'after': {'code': 'UpdateProfileRequest.parse(body)', 'note': '400 unknown field', 'tag': 'AFTER'}}, 'highlight': {'console_green': ['THE CHECK', 'THE PAGE SIZE', 'THE BUDGET', 'HOW Retry-After'], 'console_rose': ['THE RECORD AFTER', 'THE RECORD BEFORE'], 'console_amber': ['THE REQUEST', "ANA'S TOKENS", 'ANOTHER CUSTOMER'], 'console_cyan': ['THE RESPONSE']}}
